import {
  type AuthIR,
  actionAccess,
  camel,
  conditionText,
  type FieldIR,
  isUpload,
  kebab,
  type ModelAllowed,
  type ModelIR,
  modelAccess,
  pascal,
  plural,
  type SpecIR,
  type StandardActionIR,
  USER_MODEL,
} from "@smithable/core";
import { askedFields } from "./actions.js";
import { aggregatedLists } from "./formulas.js";
import { lists as listFields, references } from "./shared.js";

const HEADER =
  "// Generated by Smithable from smithable.yml and smithable.auth.yml. Do not edit: this file is overwritten on every change.\n";

type Expected = Record<
  "readOthers" | "readOwn" | "create" | "changeOthers" | "changeOwn" | "deleteOthers" | "deleteOwn",
  boolean
>;

/** What a user with `role` (or a visitor, for null) may do, as the spec says. */
function expected(access: ModelAllowed, role: string | null): Expected {
  const has = (op: keyof ModelAllowed) =>
    access[op].public || (role !== null && access[op].roles.includes(role));
  // A visitor who has not signed in owns nothing.
  const own = (op: keyof ModelAllowed) => role !== null && (has(op) || access[op].owner);
  const readOthers = has("read");
  const readOwn = own("read");
  // Changing or deleting a record needs reading it first.
  return {
    readOthers,
    readOwn,
    create: has("create"),
    changeOthers: readOthers && role !== null && access.write.roles.includes(role),
    changeOwn: readOwn && role !== null && own("write"),
    deleteOthers: readOthers && role !== null && access.delete.roles.includes(role),
    deleteOwn: readOwn && role !== null && own("delete"),
  };
}

/** A generated test value for a required field; `n` keeps unique values apart. */
function testValue(field: FieldIR, model: ModelIR): string {
  if (field.type.kind === "choice") return JSON.stringify(field.type.values[0]);
  if (field.type.kind === "relation") {
    return field.type.model === USER_MODEL
      ? "owner ?? stranger.id"
      : `insert${field.type.model}(owner).id`;
  }
  switch (field.type.name) {
    case "int":
      return "n";
    case "decimal":
      return "1.5";
    case "money":
      return "1000";
    case "bool":
      return "true";
    case "date":
      return '"2026-01-15"';
    case "datetime":
      return 'new Date("2026-01-15T10:00:00Z")';
    case "email":
      return `\`${camel(model.name)}\${n}@example.com\``;
    case "phone":
      return `\`+358 40 \${1000000 + n}\``;
    case "url":
      return `\`https://example.com/\${n}\``;
    case "file":
      // A stored document's record: the file need not exist for the access rules.
      return `{ file: \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.pdf\`, name: "test.pdf", type: "application/pdf", size: 4, ...receipt(by, "${kebab(model.name)}", "${field.name}", \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.pdf\`) }`;
    case "picture":
      // A stored picture's record: the file need not exist for the access rules.
      return `{ file: \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.webp\`, alt: "A test picture", width: 4, height: 3, ...receipt(by, "${kebab(model.name)}", "${field.name}", \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.webp\`) }`;
    case "pictures":
      // Several, at least one when required: one stored picture's record (a mutable list, as the column takes).
      return `[{ file: \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.webp\`, alt: "A test picture", width: 4, height: 3, ...receipt(by, "${kebab(model.name)}", "${field.name}", \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.webp\`) }].slice()`;
    case "files":
      return `[{ file: \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.pdf\`, name: "test.pdf", type: "application/pdf", size: 4, ...receipt(by, "${kebab(model.name)}", "${field.name}", \`${kebab(model.name)}/\${String(n).padStart(24, "0")}.pdf\`) }].slice()`;
    default:
      return `\`${model.name} ${field.name} \${n}\``;
  }
}

/**
 * A Vitest file that proves the effective access for every model and role, through the
 * same data functions the app uses, against the test database.
 */
/** A model whose test values carry a stored file (a required picture or document): sent through a data function, it comes with its sender's receipt. */
const sendsFiles = (model: ModelIR) =>
  model.fields.some(
    (f) => isUpload(f) && !f.formula && (f.required || f.unique) && f.name !== model.ownedBy,
  );

export function accessTestSource(ir: SpecIR, auth: AuthIR): string {
  const signedIn = auth.signIn !== "none";
  const roles: (string | null)[] = [...(signedIn ? auth.roles.map((r) => r.name) : []), null];
  const helpers = ir.models.map((model) => {
    // Every stored field: required and unique ones get a value, the rest are left empty.
    const fields = model.fields.filter(
      (f) => !f.formula && !(f.type.kind === "relation" && f.type.many),
    );
    const entries = fields.map((f) => {
      const key = f.type.kind === "relation" ? `${f.name}Id` : f.name;
      // A required owner still needs a user when the test acts as a visitor (owner null).
      const value =
        f.name === model.ownedBy
          ? f.required
            ? "owner ?? stranger.id"
            : "owner"
          : f.required || f.unique
            ? testValue(f, model)
            : "null";
      return `${key}: ${value}`;
    });
    const usesOwner = entries.some((e) => /\bowner\b/.test(e));
    const usesN = entries.some((e) => /\bn\b/.test(e));
    const ownerColumn = signedIn && !model.ownedBy ? ", ownerId: owner" : "";
    return `function ${camel(model.name)}Values(${usesOwner ? "owner" : "_owner"}: string | null${sendsFiles(model) ? ", by?: string | null" : ""}) {
${usesN ? "  const n = next();\n" : ""}  return { ${entries.join(", ")} } as const;
}

function insert${model.name}(owner: string | null, values: Record<string, unknown> = {}) {
  return db
    .insert(schema.${camel(plural(model.name))})
    .values({ ...${camel(model.name)}Values(owner), ...values${ownerColumn} })
    .returning()
    .get();
}`;
  });
  let updates = false;
  const describes = ir.models.map((model) => {
    const access = modelAccess(model, auth);
    const data = `${camel(model.name)}Data`;
    const values = `${camel(model.name)}Values`;
    // Visitors read only records that fit the public condition: the records here do (a list of
    // values fits with its first one).
    const where = access.read.where
      ? Object.fromEntries(
          Object.entries(access.read.where).map(([k, v]) => [k, Array.isArray(v) ? v[0] : v]),
        )
      : undefined;
    const fits = where ? `, ${JSON.stringify(where)}` : "";
    const tests = roles.map((role) => {
      const viewer = role === null ? "null" : `signedIn(${JSON.stringify(role)})`;
      const title = role === null ? "a visitor who has not signed in" : role;
      const own = role !== null;
      const by = sendsFiles(model) ? `, ${role === null ? "null" : "viewer.id"}` : "";
      // Changing a stranger's record keeps it the stranger's: with the owner in a field
      // (ownedBy), setting it to the viewer would make "delete others" a delete of their own.
      return `  test(${JSON.stringify(title)}, async () => {
    const viewer = ${viewer};
    const others = insert${model.name}(${signedIn ? "stranger.id" : "null"}${fits});
${own ? `    const own = insert${model.name}(viewer.id${fits});\n` : ""}    expect({
      readOthers: await reads(${data}, viewer, others.id),
      readOwn: ${own ? `await reads(${data}, viewer, own.id)` : "false"},
      create: await can(() => ${data}.create(viewer, ${values}(${own ? "viewer.id" : "null"}${by}))),
      changeOthers: await can(() => ${data}.update(viewer, others.id, ${values}(${signedIn ? "stranger.id" : "null"}${by}))),
      changeOwn: ${own ? `await can(() => ${data}.update(viewer, own.id, ${values}(viewer.id${by})))` : "false"},
      deleteOthers: await can(() => ${data}.remove(viewer, others.id)),
      deleteOwn: ${own ? `await can(() => ${data}.remove(viewer, own.id))` : "false"},
    }).toEqual({
${Object.entries(expected(access, role))
  .map(([k, v]) => `      ${k}: ${v},`)
  .join("\n")}
    });
  });`;
    });
    // A list is for the records themselves: related records it adds up stay out of it, since
    // some may not be the viewer's to read.
    const lists = aggregatedLists(model);
    const reader = roles.find((role) => role !== null && expected(access, role).readOwn);
    if (lists.length && reader)
      tests.push(`  test("a list carries no related records, only what they add up to", async () => {
    const viewer = signedIn(${JSON.stringify(reader)});
    insert${model.name}(viewer.id);
    for (const row of await ${data}.list(viewer)) expect(Object.keys(row)).not.toContain(${JSON.stringify(lists[0])});
  });`);
    // A record's page carries its related records as their own model shows them: a visitor is
    // not told who added them.
    // Both records fit their public conditions (a list of values with its first one).
    for (const list of signedIn && access.read.public ? listFields(model) : []) {
      const child = ir.models.find((m) => m.name === list.type.model);
      const back = child?.fields.find(
        (f) => f.type.kind === "relation" && !f.type.many && f.type.model === model.name,
      );
      const childRead = child && modelAccess(child, auth).read;
      if (!child || child.ownedBy || !back || !childRead?.public) continue;
      const childFits = Object.entries(childRead.where ?? {}).map(
        ([k, v]) => `, ${k}: ${JSON.stringify(Array.isArray(v) ? v[0] : v)}`,
      );
      tests.push(`  test("a visitor reading the ${model.name.toLowerCase()} is not told who added its ${list.name}", async () => {
    const parent = insert${model.name}(stranger.id${fits});
    insert${child.name}(stranger.id, { ${back.name}Id: parent.id${childFits.join("")} });
    const related = (await ${data}.get(null, parent.id))?.${list.name} ?? [];
    expect(related.length).toBeGreaterThan(0);
    for (const row of related) expect(row.ownerId).toBeNull();
  });`);
    }
    // A related record's title only for who may read it: through a record the viewer may read,
    // a reference to one they may not is nothing, as reading it directly is refused; and one that
    // stops fitting the public condition later disappears from what refers to it.
    for (const ref of signedIn ? references(model) : []) {
      const target = ir.models.find((m) => m.name === ref.type.model);
      if (!target || target === model) continue;
      const targetAccess = modelAccess(target, auth);
      const targetData = `${camel(target.name)}Data`;
      const viewerOf = (role: string | null) =>
        role === null ? "null" : `signedIn(${JSON.stringify(role)})`;
      const shown = (row: string, viewer: string) => `
    expect((await ${data}.get(${viewer}, ${row}.id))?.${ref.name} ?? null).toBeNull();
    expect((await ${data}.list(${viewer})).find((r) => r.id === ${row}.id)?.${ref.name} ?? null).toBeNull();`;
      const [tField, tWanted] = Object.entries(targetAccess.read.where ?? {})[0] ?? [];
      const tFlipped = target.fields.find((f) => f.name === tField);
      const tListed = targetAccess.read.where?.[tField ?? ""];
      const tOther =
        tFlipped?.type.kind === "choice"
          ? tFlipped.type.values.find((v) =>
              Array.isArray(tListed) ? !tListed.includes(v) : v !== tWanted,
            )
          : typeof tWanted === "boolean"
            ? !tWanted
            : undefined;
      // Who may not read a stranger's target: no read right at all, or only the public ones (a
      // target that does not fit the public condition is then hidden from them).
      const hiddenFrom = (r: string | null) =>
        !expected(targetAccess, r).readOthers ||
        (tOther !== undefined && !(r !== null && targetAccess.read.roles.includes(r)));
      const role = [...roles.filter((r) => r !== null), null].find(
        (r) => expected(access, r).readOthers && hiddenFrom(r),
      );
      if (role !== undefined)
        tests.push(`  test("${role === null ? "a visitor" : role} reading a ${model.name.toLowerCase()} is not shown the ${ref.name} it may not read", async () => {
    const viewer = ${viewerOf(role)};
    const hidden = insert${target.name}(stranger.id${tOther !== undefined ? `, { ${tField}: ${JSON.stringify(tOther)} }` : ""});
    const row = insert${model.name}(stranger.id, { ${ref.name}Id: hidden.id${fits ? `, ...${fits.slice(2)}` : ""} });
    expect(await reads(${targetData}, viewer, hidden.id)).toBe(false);${shown("row", "viewer")}
  });`);
      if (
        tField !== undefined &&
        tOther !== undefined &&
        expected(access, null).readOthers &&
        expected(targetAccess, null).readOthers
      ) {
        updates = true;
        const fitting = JSON.stringify(Array.isArray(tWanted) ? tWanted[0] : tWanted);
        tests.push(`  test("a ${ref.name} that stops being public disappears from the ${model.name.toLowerCase()} a visitor reads", async () => {
    const linked = insert${target.name}(stranger.id, { ${tField}: ${fitting} });
    const row = insert${model.name}(stranger.id, { ${ref.name}Id: linked.id${fits ? `, ...${fits.slice(2)}` : ""} });
    expect((await ${data}.get(null, row.id))?.${ref.name}).not.toBeNull();
    db.update(schema.${camel(plural(target.name))}).set({ ${tField}: ${JSON.stringify(tOther)} }).where(eq(schema.${camel(plural(target.name))}.id, linked.id)).run();
    expect(await reads(${targetData}, null, linked.id)).toBe(false);${shown("row", "null")}
  });`);
      }
    }
    // The public condition: a visitor reads a record that fits and not one that does not; a role
    // that reads everything reads both.
    // A list of values does not fit with a value outside it.
    const [field, wanted] = Object.entries(where ?? {})[0] ?? [];
    const flipped = model.fields.find((f) => f.name === field);
    if (where && field !== undefined && flipped) {
      const listed = access.read.where?.[field];
      const other =
        flipped.type.kind === "choice"
          ? flipped.type.values.find((v) =>
              Array.isArray(listed) ? !listed.includes(v) : v !== wanted,
            )
          : typeof wanted === "boolean"
            ? !wanted
            : undefined;
      const everything = roles.find((role) => role !== null && access.read.roles.includes(role));
      if (other !== undefined)
        tests.push(`  test("visitors read only ${model.name.toLowerCase()} records where ${conditionText(
          access.read.where ?? {},
        )}", async () => {
    const fitting = insert${model.name}(${signedIn ? "stranger.id" : "null"}, ${JSON.stringify(where)});
    const hidden = insert${model.name}(${signedIn ? "stranger.id" : "null"}, ${JSON.stringify({ ...where, [field]: other })});
    expect(await reads(${data}, null, fitting.id)).toBe(true);
    expect(await reads(${data}, null, hidden.id)).toBe(false);
    expect((await ${data}.list(null)).map((r) => r.id)).not.toContain(hidden.id);${
      everything
        ? `
    expect(await reads(${data}, signedIn(${JSON.stringify(everything)}), hidden.id)).toBe(true);`
        : ""
    }
  });`);
    }
    // A capacity: the last place goes to one, the next is refused; the referenced record cannot
    // lower its number below what is taken.
    const capacity = model.capacity;
    const per = capacity && model.fields.find((f) => f.name === capacity.per);
    if (capacity && per?.type.kind === "relation" && reader && !capacity.where) {
      const target = ir.models.find((m) => m.name === (per.type as { model: string }).model);
      const maxField = typeof capacity.max === "string" ? capacity.max.split(".")[1] : undefined;
      const fill = maxField
        ? `{ ...${camel(target?.name ?? "")}Values(viewer.id), ${maxField}: 1 }`
        : `${camel(target?.name ?? "")}Values(viewer.id)`;
      const max = maxField ? 1 : capacity.max;
      tests.push(`  test("a capacity: at most ${max} per ${per.name}, and the number cannot go below what is taken", async () => {
    const viewer = signedIn(${JSON.stringify(reader)});
    const place = db.insert(schema.${camel(plural(target?.name ?? ""))}).values({ ...${fill}${signedIn && !target?.ownedBy ? ", ownerId: viewer.id" : ""} }).returning().get();
    for (let i = 0; i < ${max}; i++)
      await (async (booker) => ${data}.create(booker, { ...${values}(viewer.id${sendsFiles(model) ? ", booker.id" : ""}), ${per.name}Id: place.id }))(signedIn(${JSON.stringify(reader)}));
    const last = signedIn(${JSON.stringify(reader)});
    await expect(${data}.create(last, { ...${values}(viewer.id${sendsFiles(model) ? ", last.id" : ""}), ${per.name}Id: place.id })).rejects.toThrow("full");${
      maxField
        ? `
    const admin = signedIn("admin");
    await expect(${camel(target?.name ?? "")}Data.update(admin, place.id, { ...${target && sendsFiles(target) ? `${camel(target.name)}Values(viewer.id, admin.id)` : fill}, ${maxField}: 0 })).rejects.toThrow("booked:${max}");`
        : ""
    }
  });`);
    }
    return `describe(${JSON.stringify(model.name)}, () => {
${tests.join("\n\n")}
});`;
  });
  // A standard action: who may run it on others' records and on their own (whoever may edit,
  // narrowed by "allow"), and that it is refused on a record its condition does not fit.
  const standard = ir.actions.filter((a): a is StandardActionIR => !a.custom);
  const overMany = new Set<string>();
  for (const action of standard) {
    const model = ir.models.find((m) => m.name === action.on) as ModelIR;
    const access = modelAccess(model, auth);
    const allowed = actionAccess(action, auth, ir.models);
    const run = `run${pascal(action.name)}`;
    // A record the condition fits (a list of values fits with its first one), and one it does not.
    const fits = Object.fromEntries(
      Object.entries(action.when ?? {}).map(([k, v]) => [k, Array.isArray(v) ? v[0] : v]),
    );
    const readable = access.read.where
      ? Object.fromEntries(
          Object.entries(access.read.where).map(([k, v]) => [k, Array.isArray(v) ? v[0] : v]),
        )
      : {};
    const values = JSON.stringify({ ...readable, ...fits });
    // What the action asks for, as a test gives it: a value each field accepts.
    const askedValues = askedFields(action).map((x) => {
      const target = ir.models.find((m) => m.name === x.model) as ModelIR;
      const field = target.fields.find((f) => f.name === x.field) as FieldIR;
      return `${JSON.stringify(x.key)}: ${testValue(field, target)}`;
    });
    // Each run gets its own values (a unique number must differ between two copies).
    const fresh = askedValues.some((v) => /\bn\b/.test(v));
    const asked = !askedValues.length ? "" : fresh ? ", ask()" : `, { ${askedValues.join(", ")} }`;
    const counter = fresh
      ? `    const ask = () => {\n      const n = next();\n      return { ${askedValues.join(", ")} };\n    };\n`
      : "";
    const table = `schema.${camel(plural(model.name))}`;
    // Refused, the action writes nothing: the record is as it was (an update it began rolls back).
    const before = (record: string) =>
      `    const ${record}Before = JSON.stringify(db.select().from(${table}).where(eq(${table}.id, ${record}.id)).get());\n`;
    const unchanged = (record: string) =>
      `    expect(JSON.stringify(db.select().from(${table}).where(eq(${table}.id, ${record}.id)).get())).toBe(${record}Before);\n`;
    const tests = roles.map((role) => {
      const viewer = role === null ? "null" : `signedIn(${JSON.stringify(role)})`;
      const can = expected(access, role);
      const listed = role !== null && allowed.roles.includes(role);
      const asOwner = role !== null && allowed.owner;
      const othersOk = can.readOthers && listed;
      const ownOk = can.readOwn && (listed || asOwner);
      return `  test(${JSON.stringify(role === null ? "a visitor who has not signed in" : role)}, async () => {
    const viewer = ${viewer};
${counter}    const others = insert${model.name}(${signedIn ? "stranger.id" : "null"}, ${values});
${othersOk ? "" : before("others")}${
  role !== null
    ? `    const own = insert${model.name}(viewer.id, ${values});
${ownOk ? "" : before("own")}`
    : ""
}    expect({
      others: await can(() => ${run}(viewer, others.id${asked})),
      own: ${role !== null ? `await can(() => ${run}(viewer, own.id${asked}))` : "false"},
    }).toEqual({ others: ${othersOk}, own: ${ownOk} });
${othersOk ? "" : unchanged("others")}${role !== null && !ownOk ? unchanged("own") : ""}  });`;
    });
    const [field, wanted] = Object.entries(action.when ?? {})[0] ?? [];
    const flipped = model.fields.find((f) => f.name === field);
    const other =
      flipped?.type.kind === "choice"
        ? flipped.type.values.find((v) => !(Array.isArray(wanted) ? wanted : [wanted]).includes(v))
        : typeof wanted === "boolean"
          ? !wanted
          : undefined;
    const runner = roles.find((role) => role !== null && allowed.roles.includes(role));
    if (field !== undefined && other !== undefined && runner)
      tests.push(`  test("refused on a record where ${field} is not ${Array.isArray(wanted) ? wanted.join(" or ") : String(wanted)}", async () => {
${counter}    const viewer = signedIn(${JSON.stringify(runner)});
    const record = insert${model.name}(viewer.id, ${JSON.stringify({ ...readable, ...fits, [field]: other })});
    await expect(${run}(viewer, record.id${asked})).rejects.toThrow("This cannot be done now.");
  });`);
    // Over chosen records (actions.md §9): the ones it fits change, the others are skipped,
    // and a visitor's run changes nothing.
    if (field !== undefined && other !== undefined && runner && !action.copy) {
      overMany.add(action.name);
      const strangers = signedIn && !expected(access, runner).readOthers;
      tests.push(`  test("over chosen records, only those it fits and may run on change", async () => {
${counter}    const viewer = signedIn(${JSON.stringify(runner)});
    const fitting = insert${model.name}(viewer.id, ${values});
    const notFitting = insert${model.name}(viewer.id, ${JSON.stringify({ ...readable, ...fits, [field]: other })});
${strangers ? `    const others = insert${model.name}(stranger.id, ${values});\n` : ""}${before("notFitting")}    expect(await ${run}Many(viewer, [fitting.id, fitting.id, notFitting.id${strangers ? ", others.id" : ""}]${asked})).toEqual({ changed: 1, skipped: ${strangers ? 2 : 1} });
${unchanged("notFitting")}    const again = insert${model.name}(viewer.id, ${values});
${before("again")}    await ${run}Many(null, [again.id]${asked}).catch(() => undefined);
${unchanged("again")}  });`);
    }
    describes.push(`describe(${JSON.stringify(`the ${action.name} action`)}, () => {
${tests.join("\n\n")}
});`);
  }
  // The audit log (docs/design/logging.md §3.3): for the first model some role may create,
  // change and delete its own records of, the three lines name that person and the change.
  const audited = signedIn
    ? ir.models
        .flatMap((model) =>
          roles.map((role) => ({ model, role, can: expected(modelAccess(model, auth), role) })),
        )
        .find(({ role, can }) => role !== null && can.create && can.changeOwn && can.deleteOwn)
    : undefined;
  if (audited) {
    const { model, role } = audited;
    const data = `${camel(model.name)}Data`;
    const values = `${camel(model.name)}Values`;
    describes.push(`describe("the audit log", () => {
  test("names who created, changed and deleted a record, and what changed", async () => {
    const viewer = signedIn(${JSON.stringify(role)});
    const made = await ${data}.create(viewer, ${values}(viewer.id${sendsFiles(model) ? ", viewer.id" : ""}));
    await ${data}.update(viewer, made.id, ${values}(viewer.id${sendsFiles(model) ? ", viewer.id" : ""}));
    await ${data}.remove(viewer, made.id);
    const lines = db
      .select()
      .from(auditLog)
      .where(and(eq(auditLog.model, ${JSON.stringify(model.name)}), eq(auditLog.recordId, made.id)))
      .all();
    expect(lines.map((l) => [l.action, l.who, l.role])).toEqual([
      ["created", viewer.id, viewer.role],
      ["changed", viewer.id, viewer.role],
      [${JSON.stringify(model.trash ? "trashed" : "deleted")}, viewer.id, viewer.role],
    ]);
    // Only the line that deleted it keeps the record's name (its title by then); no field's
    // value is stored.
    expect(lines.map((l) => Boolean(l.title))).toEqual([false, false, true]);
    expect(JSON.stringify(lines[1]?.fields ?? [])).not.toContain(":");

    // Forget in the log: administrators only; it blanks the deleted record's name and is logged by id.
${roles.some((r) => r !== null && r !== "admin") ? `    expect(() => forgetInLog(signedIn(${JSON.stringify(roles.find((r) => r !== null && r !== "admin") ?? null)}), { model: ${JSON.stringify(model.name)}, record: made.id })).toThrow(AccessDenied);\n` : ""}    forgetInLog(signedIn("admin"), { model: ${JSON.stringify(model.name)}, record: made.id });
    const after = db.select().from(auditLog).where(and(eq(auditLog.model, ${JSON.stringify(model.name)}), eq(auditLog.recordId, made.id))).all();
    expect(after.map((l) => l.title)).toEqual([null, null, null]);
    const forgot = db.select().from(auditLog).where(eq(auditLog.action, "forgotten in the log")).all().at(-1);
    expect(forgot).toMatchObject({ title: null, details: { model: ${JSON.stringify(model.name)}, record: made.id } });
  });

  test("keeps the client's details and a deleted record's name 90 days, and a line 12 months", () => {
    const day = 24 * 60 * 60 * 1000;
    const line = (daysAgo: number) =>
      db
        .insert(auditLog)
        .values({ at: new Date(Date.now() - daysAgo * day), who: "test", action: "deleted", title: "Old", address: "10.0.0.1", browser: "test" })
        .returning()
        .get();
    const recent = line(10);
    const older = line(100);
    const oldest = line(400);
    pruneAudit();
    const row = (id: number) => db.select().from(auditLog).where(eq(auditLog.id, id)).get();
    expect(row(recent.id)).toMatchObject({ title: "Old", address: "10.0.0.1" });
    expect(row(older.id)).toMatchObject({ title: null, address: null, browser: null, action: "deleted" });
    expect(row(oldest.id)).toBeUndefined();
  });
});`);
  }
  const imports = [
    ...ir.models.map((m) => `import { ${camel(m.name)}Data } from "./${kebab(m.name)}.server";`),
    ...standard.map(
      (a) =>
        `import { run${pascal(a.name)}${overMany.has(a.name) ? `, run${pascal(a.name)}Many` : ""} } from "./actions/${kebab(a.name)}.server";`,
    ),
  ];
  return `${HEADER}// For every model and role: which records a user can read, create, change and delete.
// "Own" records are owned by the user; "others" by someone else.
${audited ? 'import { and, eq } from "drizzle-orm";\n' : standard.length || updates ? 'import { eq } from "drizzle-orm";\n' : ""}import { describe, expect, test } from "vitest";
import { db } from "#/db";
${signedIn || audited ? `import { ${[...(signedIn ? ["user"] : []), ...(audited ? ["auditLog"] : [])].sort().join(", ")} } from "#/db/schema";\n` : ""}import * as schema from "#/db/schema";
import { AccessDenied${signedIn ? ", type Viewer" : ""} } from "#/kit/access";
${audited ? 'import { forgetInLog, pruneAudit } from "#/kit/audit.server";\n' : ""}${ir.models.some(sendsFiles) ? 'import { receiptFor } from "#/kit/receipts.server";\n' : ""}${imports.join("\n")}

let counter = 0;
const next = () => ++counter;
${
  signedIn
    ? `
/** A new signed-in user with the role. */
function signedIn(role: string): Viewer {
  const n = next();
  const viewer = { id: \`test-user-\${n}\`, name: \`Test \${role} \${n}\`, email: \`user\${n}@example.com\`, role };
  db.insert(user).values(viewer).run();
  return viewer;
}

/** Owns the records that are someone else's. */
const stranger = signedIn(${JSON.stringify(auth.defaultRole)});
`
    : ""
}
${
  ir.models.some(sendsFiles)
    ? `/** A test file's receipt, as its upload gives one to \`by\`; none for a record put in directly. */
function receipt(by: string | null | undefined, model: string, field: string, file: string) {
  return by === undefined ? {} : { receipt: receiptFor(by, model, field, file) };
}

`
    : ""
}/** Whether the action is allowed; any other failure fails the test. */
async function can(action: () => unknown): Promise<boolean> {
  try {
    await action();
    return true;
  } catch (error) {
    if (error instanceof AccessDenied) return false;
    throw error;
  }
}

/** Whether the viewer can open the record and sees it in the list. */
async function reads(
  data: { get(viewer: never, id: number): Promise<unknown>; list(viewer: never): Promise<{ id: number }[]> },
  viewer: unknown,
  id: number,
): Promise<boolean> {
  const listed = await data.list(viewer as never).then(
    (rows) => rows.some((row) => row.id === id),
    (error) => {
      if (error instanceof AccessDenied) return false;
      throw error;
    },
  );
  return listed && (await data.get(viewer as never, id)) !== null;
}

${helpers.join("\n\n")}

${describes.join("\n\n")}
`;
}
